{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver swims through a shattered window into the ruined city.",
      "visual_description": "A broken stained-glass window frames the glass diver as they emerge into a courtyard littered with fallen columns and faded royal banners.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unrolls a map at the city gates.",
      "visual_description": "Mara stands before the rusted iron castle gates, her compass glinting as she traces a path through the rubble with ink-stained fingers.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning near a cursed tower.",
      "visual_description": "The lamp's single eye glows red as it sits atop a broken parapet, casting long shadows from the twisted spire behind it.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts ahead through a narrow alley.",
      "visual_description": "The small clockwork fox slips between fallen stones, its key-wind tail ticking softly as blue eyes scan for danger.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector snores on a stack of ledgers near the main square.",
      "visual_description": "He is slumped against a crumbling fountain, stamped papers stuck to his sleeves, ledger book as a pillow, oblivious to the patrol passing nearby.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara reads the map aloud while the glass diver peers into a reflecting pool.",
      "visual_description": "Mara points to a symbol on the map as the glass diver's helmet reflects the ruined palace towers in the water's surface.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp warns of a trap behind a magic door.",
      "visual_description": "The lamp's flame flares blue as it hovers before an ornate door inscribed with glowing runes, its eye wide with alarm.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox discovers a hidden passage beneath old royal banners.",
      "visual_description": "The fox nuzzles aside a tattered banner embroidered with a faded crest, revealing a dark stairwell descending into the earth.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver swims through a mirror into a sealed chamber.",
      "visual_description": "Glass diver steps through a full-length mirror into a room filled with dust and a single glowing crystal, their coat reflecting the light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara marks the map as the oracle lamp reveals a patrol route.",
      "visual_description": "Mara scratches a line on the parchment while the lamp casts a beam that outlines armored shadows moving beyond a colonnade.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector stirs but does not wake as the group passes.",
      "visual_description": "He mumbles in his sleep, a stamped paper fluttering loose, as the glass diver tiptoes past his mossy bench.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox relays a signal from the tower's base.",
      "visual_description": "The fox taps its metal paw against a stone, producing a rhythmic click that echoes up the spiral stairs.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver climbs the cursed tower using window frames as handholds.",
      "visual_description": "Glass diver leaps from sill to sill, shattered glass swirling around their helmet, the tower's curse causing shadows to writhe.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp illuminates a keyhole on a magic door.",
      "visual_description": "The lamp's flame narrows into a thin beam that lights the keyhole, revealing a faint mechanism inside the door's lock.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Mara deciphers a riddle carved into the door's frame.",
      "visual_description": "Mara runs her fingers over the letters, her compass needle spinning as she mutters solutions under her breath.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The sleeping tax collector rolls over and blocks a patrol's path.",
      "visual_description": "He shifts in his sleep, sprawling across the cobblestones, causing an armored patrol to halt and turn away.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver retrieves the rescue target from a mirrored cell.",
      "visual_description": "Glass diver reaches through a mirror's surface to grasp a hand, pulling a figure free from the reflective prison as the room shimmers.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes across a crumbling bridge as dawn breaks.",
      "visual_description": "Glass diver, Mara, tin fox, oracle lamp, and the sleeping tax collector hurry across a stone bridge with missing arches, the ruined city behind them silhouetted against the rising sun.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

